INSERT INTO "projects" ("id", "slug", "title_short", "title_short_en", "title_full", "title_full_en", "summary", "summary_en", "detail_json", "detail_json_en", "links_json", "sort_order", "visible") VALUES ('project:uncode', 'uncode', 'UNCode', 'UNCode', 'UNCode', 'UNCode', 'Sistema interactivo para el aprendizaje y la evaluación automática de habilidades de programación de computadores.', 'Interactive system for learning and automatic evaluation of computer programming skills.', '[]', '[]', '[{"label":"Sitio","label_en":"Site","url":"https://juezun.github.io/"},{"label":"Repositorio","label_en":"Repository","url":"https://github.com/JuezUN/"},{"label":"Plataforma","label_en":"Platform","url":"https://uncode.unal.edu.co/courselist"}]', '1', 'yes');
INSERT INTO "projects" ("id", "slug", "title_short", "title_short_en", "title_full", "title_full_en", "summary", "summary_en", "detail_json", "detail_json_en", "links_json", "sort_order", "visible") VALUES ('project:paradigmas', 'paradigmas', 'Paradigmas de programación', 'Programming paradigms', 'Paradigmas de programación', 'Programming paradigms', 'Sitio web educativo para la introducción a los paradigmas de programación y tutoriales de distintos lenguajes.', 'Educational website introducing programming paradigms, including tutorials for different languages.', '[]', '[]', '[{"label":"Sitio","label_en":"Site","url":"https://ferestrepoca.github.io/paradigmas-de-programacion/"}]', '2', 'yes');
INSERT INTO "projects" ("id", "slug", "title_short", "title_short_en", "title_full", "title_full_en", "summary", "summary_en", "detail_json", "detail_json_en", "links_json", "sort_order", "visible") VALUES ('project:iris', 'iris', 'IRIS', 'IRIS', 'IRIS', 'IRIS', 'Herramienta de accesibilidad para que los estudiantes en situación de discapacidad visual puedan percibir imágenes usando las manos.', 'Accessibility tool for visually impaired students to perceive images using their hands.', '[]', '[]', '[{"label":"Sitio","label_en":"Site","url":"https://www.duto.org/"}]', '3', 'yes');
INSERT INTO "projects" ("id", "slug", "title_short", "title_short_en", "title_full", "title_full_en", "summary", "summary_en", "detail_json", "detail_json_en", "links_json", "sort_order", "visible") VALUES ('project:she', 'she', 'SHE', 'SHE', 'Software Hardening Environment', 'Software Hardening Environment', 'Herramienta para el endurecimiento automático de código fuente para el diseño de sistemas embebidos confiables.', 'Tool for the automatic hardening of source code in the design of dependable embedded systems.', '[{"heading":"¿Qué es SHE?","bullets":["SHE: Software Hardening Environment (Entorno de \"Endurecimiento\" de Software).","Es una herramienta para el desarrollo de software tolerante a fallos.","Permite el diseño e implementación de técnicas de tolerancia a fallos basadas en software, las cuales pueden ser aplicadas a los programas de forma automática.","La estrategia de \"endurecimiento\" (protección) está basada en reglas de transformación del código a bajo nivel, es decir, lenguaje ensamblador.","Permite aplicar las técnicas software de tolerancia a fallos de forma selectiva, protegiendo sólo las partes críticas del programa. Así, se reducen los overheads y se ofrece mayor flexibilidad al diseñador.","Multiplataforma (probado en GNU/Linux y Windows)."]},{"heading":"Microprocesadores soportados","bullets":["Xilinx PicoBlaze 8-bit KCPSM3.","Xilinx PicoBlaze 8-bit KCPSM6.","Texas Instruments MSP430 16-bit.","Puede soportar muchos más."]},{"heading":"Prueba SHE online","bullets":["Disponible en el Fault Tolerance Lab (University of Alicante - España)."]},{"heading":"Más información","bullets":["Felipe Restrepo-Calle et al. Selective SWIFT-R. JETTA 2013. DOI:10.1007/s10836-013-5416-6.","Antonio Martínez-Álvarez et al. Compiler-Directed Soft Error Mitigation. IEEE TDSC 2012. DOI:10.1109/TDSC.2011.54.","Sergio Cuenca-Asensi et al. A novel co-design approach for soft errors mitigation. IEEE TNS 2011. DOI:10.1109/TNS.2011.2112379."]}]', '[{"heading":"What is SHE?","bullets":["SHE: Software Hardening Environment.","Tool for fault-tolerant software development.","It allows the design and implementation of software-based mitigation techniques, which can be automatically applied into programs.","The hardening (protection) strategy is based on code transformation rules at low level, i.e., assembly code.","It permits applying software-based fault tolerance techniques selectively, protecting only the most critical parts of the program—reducing overheads and giving designers more flexibility.","Multiplatform: tested in Linux and Windows."]},{"heading":"Supported microprocessors","bullets":["Xilinx PicoBlaze 8-bit KCPSM3.","Xilinx PicoBlaze 8-bit KCPSM6.","Texas Instruments MSP430 16-bit.","More can be included."]},{"heading":"Try it online","bullets":["Available at the Fault Tolerance Lab (University of Alicante - Spain)."]},{"heading":"More information","bullets":["Felipe Restrepo-Calle et al. Selective SWIFT-R. JETTA 2013. DOI:10.1007/s10836-013-5416-6.","Antonio Martínez-Álvarez et al. Compiler-Directed Soft Error Mitigation. IEEE TDSC 2012. DOI:10.1109/TDSC.2011.54.","Sergio Cuenca-Asensi et al. A novel co-design approach for soft errors mitigation. IEEE TNS 2011. DOI:10.1109/TNS.2011.2112379."]}]', '[{"label":"Fault Tolerance Lab","label_en":"Fault Tolerance Lab","url":"http://www.iuii.ua.es/experimenter/"},{"label":"DOI Selective SWIFT-R","label_en":"DOI Selective SWIFT-R","url":"https://doi.org/10.1007/s10836-013-5416-6"}]', '4', 'yes');
INSERT INTO "projects" ("id", "slug", "title_short", "title_short_en", "title_full", "title_full_en", "summary", "summary_en", "detail_json", "detail_json_en", "links_json", "sort_order", "visible") VALUES ('project:ftxac', 'ftxac', 'FTxAC', 'FTxAC', 'Fault Tolerance × Approximate Computing', 'Fault Tolerance × Approximate Computing', 'Uso de computación aproximada y endurecimiento selectivo para reducir overheads en sistemas embebidos tolerantes a fallos.', 'Using approximate computing and selective hardening to reduce overheads in fault-tolerant embedded systems.', '[]', '[]', '[]', '5', 'yes');
